class Account {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;

    Account(String accountId, String holderName, BigDecimal balance) {
        this.accountId = accountId; this.holderName = holderName; this.balance = balance;
    }
    String getAccountId() { return accountId; }
    BigDecimal getBalance() { return balance; }
    void debit(BigDecimal amt)  { this.balance = this.balance.subtract(amt); }
    void credit(BigDecimal amt) { this.balance = this.balance.add(amt); }
}

// ─── Would be in TransferService.java in a real project ───
class TransferService {
    private static final Logger log = Logger.getLogger(TransferService.class.getName());

    // transfer() frame calls debit() frame then credit() frame — each on the thread's STACK.
    void transfer(Account from, Account to, BigDecimal amount) {
        debit(from, amount);           // push debit() frame
        credit(to, amount);            // push credit() frame
        log.info(() -> "Transfer of " + amount + " from " + from.getAccountId()
                + " to " + to.getAccountId() + " complete");
    }
    private void debit(Account acc, BigDecimal amt)  { acc.debit(amt); }
    private void credit(Account acc, BigDecimal amt) { acc.credit(amt); }
}

// ─── Would be in MemoryInspector.java in a real project ───
class MemoryInspector {
    private static final Logger log = Logger.getLogger(MemoryInspector.class.getName());

    void report(String label) {
        Runtime rt = Runtime.getRuntime();
        long usedHeap = (rt.totalMemory() - rt.freeMemory()) / (1024 * 1024);
        long maxHeap  = rt.maxMemory() / (1024 * 1024);
        // Non-heap (Metaspace) via MemoryMXBean.
        var nonHeap = java.lang.management.ManagementFactory.getMemoryMXBean()
                .getNonHeapMemoryUsage().getUsed() / (1024 * 1024);
        log.info(String.format("%s -> Heap used=%dMB / max=%dMB | NonHeap(Metaspace+CodeCache)=%dMB",
                label, usedHeap, maxHeap, nonHeap));
    }
}
